import warnings

def complete_lesson(learner_id, lesson_id, completed_at=None):
    if completed_at is None:
        warnings.warn(
            'Calling complete_lesson without completed_at is deprecated; pass an explicit timestamp.',
            DeprecationWarning,
            stacklevel=2,
        )
        completed_at = 'legacy-default'
    return {'learner_id': learner_id, 'lesson_id': lesson_id, 'completed_at': completed_at}

print(complete_lesson('ana', 'loops', '2026-10-02T09:00:00Z'))

