import warnings

def format_progress(lesson_id, style=None):
    if style is None:
        warnings.warn(
            'style=None is deprecated; pass style="short" explicitly.',
            DeprecationWarning,
            stacklevel=2,
        )
        style = 'short'
    return {'lesson_id': lesson_id, 'style': style}

assert format_progress('loops', style='short') == {'lesson_id': 'loops', 'style': 'short'}
